120: 			}
121: 
122: 			const [, processBinPath] = process.argv;
123: 			let npmBinPath;
124: 
125: 			try {
126: 				npmBinPath = execCommand("npm", npmBinArgs);
127: 			} catch (e) {
128: 				log.error(
