130: 				);
131: 				throw e;
132: 			}
133: 
134: 			const isGlobal = isChildOfDirectory(npmBinPath, processBinPath);
135: 			let pkgVersion = parsedStdout.dependencies.eslint.version;
136: 
137: 			if ((global && isGlobal) || (!global && !isGlobal)) {
